import{_ as t,o as e,c as r,aj as o}from"./chunks/framework.Cn87zHeG.js";const q=JSON.parse('{"title":"开关机与安全","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"faq/power-safety.md","filePath":"faq/power-safety.md"}'),i={name:"faq/power-safety.md"};function s(l,a,n,h,f,d){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="开关机与安全" tabindex="-1">开关机与安全 <a class="header-anchor" href="#开关机与安全" aria-label="Permalink to &quot;开关机与安全&quot;">​</a></h1><p><a href="/onerobot-H1/downloads/faq/power-guide.pdf">下载《H1机器人电源开关说明》（PDF）</a></p><h2 id="q1" tabindex="-1">Q1. H1 怎么开机？ <a class="header-anchor" href="#q1" aria-label="Permalink to &quot;Q1. H1 怎么开机？ {#q1}&quot;">​</a></h2><p>先完成<a href="./../getting-started/first-use.html#preflight">开机前检查</a>，确认急停已解除、已配置的电源开关均处于通电状态。<strong>是否配有遥控开关，以收到的实物为准。</strong> 开关位置和操作步骤见<a href="./../getting-started/first-use.html#power-on">开机</a>。</p><h2 id="q2" tabindex="-1">Q2. 怎么关机 / 断电？ <a class="header-anchor" href="#q2" aria-label="Permalink to &quot;Q2. 怎么关机 / 断电？ {#q2}&quot;">​</a></h2><p>正常关机前，先让机器人处于安全姿态，停止任务、退出控制模式并保存所需数据，再操作电源开关断电，详见<a href="./../getting-started/first-use.html#power-off">正常关机</a>。<strong>紧急情况立即按下本体物理急停。</strong></p><h2 id="q3" tabindex="-1">Q3. 应急开关（急停）怎么用？什么时候用？ <a class="header-anchor" href="#q3" aria-label="Permalink to &quot;Q3. 应急开关（急停）怎么用？什么时候用？ {#q3}&quot;">​</a></h2><p>出现失控、异常抖动、即将碰撞等危险情况时，立即按下本体红色急停按钮，可隔着红胶套按。软件急停无效时，立即使用本体物理急停或直接断电。解除方式和注意事项见<a href="./../getting-started/first-use.html#emergency-stop">急停</a>。</p><h2 id="q4" tabindex="-1">Q4. 机身指示灯不同颜色代表什么状态？ <a class="header-anchor" href="#q4" aria-label="Permalink to &quot;Q4. 机身指示灯不同颜色代表什么状态？ {#q4}&quot;">​</a></h2><p>白灯常亮表示正常，红灯常亮表示故障。完整灯效对照见<a href="./../getting-started/first-use.html#indicators">状态指示灯</a>。</p><h2 id="q5" tabindex="-1">Q5. 操作机器人有哪些基本安全须知？ <a class="header-anchor" href="#q5" aria-label="Permalink to &quot;Q5. 操作机器人有哪些基本安全须知？ {#q5}&quot;">​</a></h2><ul><li>H1 调试工具的运动操作前，应清空机器人运动范围，确保无人、无障碍物，并保持本体物理急停可用，具体准备要求见<a href="./../getting-started/debug-tool.html#status">使用说明</a>。</li><li>运动过程中人员不要靠近，保持通道畅通。</li><li>急停按钮（软件）无效时，立即按本体物理急停或直接断电。</li><li><strong>固件升级（OTA）过程中严禁给机器人断电。</strong></li><li>手柄操作时禁止重复按同一个按键（详见<a href="./controller.html#q10">手柄使用注意事项</a>）。</li></ul><p>首次使用请先阅读<a href="./../getting-started/first-use.html#preflight">开机前检查</a>和<a href="./../getting-started/first-use.html#controller-safety">手柄操作注意事项</a>。</p>',13)])])}const u=t(i,[["render",s]]);export{q as __pageData,u as default};
